<?php require __DIR__.'/app/bootstrap.php'; require __DIR__.'/includes/layout.php'; render_header('Цены'); ?><section class="section"><div class="container"><h1>Цены</h1><?php try{$sections=db()->query('SELECT * FROM csPriceSections ORDER BY ID')->fetchAll();foreach($sections as $s):?><div class="content-card"><h2><?=htmlspecialchars(legacy($s['Name']??''))?></h2><?php $q=db()->prepare('SELECT * FROM csPriceItems WHERE PriceSectionID=? ORDER BY ID');$q->execute([$s['ID']]);foreach($q->fetchAll() as $i):?><p><b><?=htmlspecialchars(legacy($i['Name']??''))?></b> <?=htmlspecialchars((string)($i['Price']??''))?></p><?php endforeach;?></div><?php endforeach;}catch(Throwable){echo '<p>Информация о ценах пока недоступна.</p>';} ?></div></section><?php render_footer();
